import { metaSchema, pageSchema } from 'fumadocs-core/source/schema';
import { defineConfig, defineDocs } from 'fumadocs-mdx/config';

/**
 * The documentation is generated by the Go tool at the repository root
 * (`pnpm docs:gen`), not written by hand. Every page carries `title` and
 * `description` frontmatter and uses only standard markdown.
 */
export const docs = defineDocs({
  dir: 'content/docs',
  docs: {
    // Each page's body is its own chunk, loaded when the page is rendered,
    // instead of every page (thousands, with the releases' docs) being
    // imported into one module graph, which ran the build out of memory.
    async: true,
    schema: pageSchema,
    postprocess: {
      // Keeps the processed markdown of each page, which llms.txt serves.
      includeProcessedMarkdown: true
    }
  },
  meta: {
    schema: metaSchema
  }
});

export default defineConfig({
  mdxOptions: {
    rehypeCodeOptions: {
      themes: {
        light: 'github-light-default',
        dark: 'github-dark-default'
      }
    }
  }
});
